package com.myaaptha.domain.relationship;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.myaaptha.domain.contacts.AddressBookService;
import com.myaaptha.domain.contacts.AddressBookService.Entry;
import com.myaaptha.platform.security.FieldEncryption;
import jakarta.validation.Valid;
import jakarta.validation.constraints.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.Principal;
import java.text.Normalizer;
import java.util.*;
import java.util.regex.*;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;

@RestController @RequestMapping("/api/relationship-trees")
public class ReviewedTrees {
 public record Node(@NotBlank @Size(max=80) String key,Long contactId,@NotBlank @Size(max=200) String name,@NotBlank @Size(max=80) String relation,@Size(max=80) String parentKey,@jakarta.validation.constraints.Pattern(regexp="MALE|FEMALE|OTHER|UNSPECIFIED") String gender){}
 public record Tree(Long id,String sourceKey,String name,String reason,String confidence,List<Node> nodes,long version){}
 public record Card(Long id,String key,String name,String reason,String confidence,int count,List<Node> preview,long version){}
 public record Suggestions(long scannedContacts,int totalSuggestions,int dismissedCount,int smallGroupsSkipped,List<Card> items,Integer nextOffset){}
 public record SavedPage(List<Card> items,Long nextCursor){}
 public record Save(@NotBlank @Size(max=200) String name,@jakarta.validation.constraints.Pattern(regexp="[a-f0-9]{64}") String sourceKey,@Size(max=1000) String reason,@NotNull @Size(min=3,max=50000) List<@NotNull @Valid Node> nodes,@AssertTrue(message="Review this tree before saving") boolean reviewed,Long version){}
 public record Key(@NotBlank @jakarta.validation.constraints.Pattern(regexp="[a-f0-9]{64}") String key){}
 public record Contact(long id,String name){}
 public record ContactPage(List<Contact> items,Long nextCursor,long total){}
 private record Group(String key,String name,String reason,String confidence,int rank,LinkedHashMap<Long,Node> nodes){}
 private record Generated(long count,int small,List<Tree> trees){}
 private static final Set<String> MAIL_PROVIDERS=Set.of("gmail.com","googlemail.com","yahoo.com","yahoo.co.in","ymail.com","outlook.com","hotmail.com","live.com","msn.com","icloud.com","me.com","aol.com","rediffmail.com","proton.me","protonmail.com","mail.com","gmx.com","zoho.com");
 private static final Set<String> GENERIC=Set.of("contacts","my contacts","all contacts","imported","starred in android","friends","other contacts","mobile","home","work","family");
 private final AddressBookService book;private final JdbcTemplate db;private final ObjectMapper json;private final FieldEncryption encryption;
 public ReviewedTrees(AddressBookService book,JdbcTemplate db,ObjectMapper json,FieldEncryption encryption){this.book=book;this.db=db;this.json=json;this.encryption=encryption;}
 private long owner(Principal p){return Long.parseLong(p.getName());}
 @GetMapping("/contacts") public ContactPage contacts(Principal p,@RequestParam(defaultValue="0") long afterId,@RequestParam(defaultValue="") String q){var page=book.list(owner(p),afterId,50,q,null);return new ContactPage(page.items().stream().map(c->new Contact(c.id(),c.displayName())).toList(),page.nextCursor(),page.total());}
 @GetMapping("/suggestions") public Suggestions suggestions(Principal p,@RequestParam(defaultValue="0") int offset,@RequestParam(defaultValue="24") int limit){if(offset<0||limit<1||limit>100)throw bad("Invalid suggestion page");long user=owner(p);var generated=generate(user);Set<String> dismissed=new HashSet<>(db.queryForList("SELECT source_key FROM dismissed_relationship_trees WHERE user_id=?",String.class,user));Set<String> saved=new HashSet<>(db.queryForList("SELECT source_key FROM reviewed_relationship_trees WHERE user_id=? AND source_key IS NOT NULL",String.class,user));var available=generated.trees().stream().filter(t->!dismissed.contains(t.sourceKey())&&!saved.contains(t.sourceKey())).toList();var page=available.stream().skip(offset).limit(limit).map(this::card).toList();return new Suggestions(generated.count(),available.size(),dismissed.size(),generated.small(),page,offset+page.size()<available.size()?offset+page.size():null);}
 @GetMapping("/suggestions/{key}") public Tree suggestion(Principal p,@PathVariable String key){return proposal(owner(p),key);}
 @PostMapping("/suggestions/dismiss") @Transactional public void dismiss(Principal p,@Valid @RequestBody Key request){long user=owner(p);lock(user);proposal(user,request.key());if(db.queryForObject("SELECT COUNT(*) FROM dismissed_relationship_trees WHERE user_id=? AND source_key=?",Integer.class,user,request.key())==0)db.update("INSERT INTO dismissed_relationship_trees(user_id,source_key) VALUES(?,?)",user,request.key());}
 @PostMapping("/suggestions/restore") @Transactional public void restore(Principal p){db.update("DELETE FROM dismissed_relationship_trees WHERE user_id=?",owner(p));}
 @GetMapping public SavedPage saved(Principal p,@RequestParam(defaultValue="0") long afterId){if(afterId<0)throw bad("Invalid tree page");var rows=db.query("SELECT * FROM reviewed_relationship_trees WHERE user_id=? AND id>? ORDER BY id LIMIT 25",(rs,n)->decode(rs.getLong("id"),rs.getString("source_key"),rs.getString("tree_data"),rs.getLong("version")),owner(p),afterId);var page=rows.stream().limit(24).toList();return new SavedPage(page.stream().map(this::card).toList(),rows.size()>24?page.getLast().id():null);}
 @GetMapping("/{id}") public Tree tree(Principal p,@PathVariable long id){return required(owner(p),id);}
 @PostMapping @Transactional public Tree create(Principal p,@Valid @RequestBody Save input){long user=owner(p);lock(user);validate(user,input);if(input.sourceKey()!=null){var existing=db.queryForList("SELECT id FROM reviewed_relationship_trees WHERE user_id=? AND source_key=?",Long.class,user,input.sourceKey());if(!existing.isEmpty()){var saved=required(user,existing.getFirst());if(saved.name().equals(input.name().trim())&&saved.nodes().equals(input.nodes()))return saved;throw new ResponseStatusException(HttpStatus.CONFLICT,"This suggestion was already saved. Open it in My trees to edit");}proposal(user,input.sourceKey());}var key=new GeneratedKeyHolder();String data=encode(input);db.update(connection->{var statement=connection.prepareStatement("INSERT INTO reviewed_relationship_trees(user_id,source_key,tree_data) VALUES(?,?,?)",new String[]{"id"});statement.setLong(1,user);statement.setString(2,input.sourceKey());statement.setString(3,data);return statement;},key);return required(user,Objects.requireNonNull(key.getKey()).longValue());}
 @PostMapping("/{id}/update") @Transactional public Tree update(Principal p,@PathVariable long id,@Valid @RequestBody Save input){long user=owner(p);lock(user);var original=required(user,id);validate(user,input);if(input.version()==null||input.version()!=original.version())throw new ResponseStatusException(HttpStatus.CONFLICT,"This tree changed on another device. Reopen it before saving");db.update("UPDATE reviewed_relationship_trees SET tree_data=?,version=version+1,updated_at=CURRENT_TIMESTAMP WHERE id=? AND user_id=?",encode(input),id,user);return required(user,id);}
 @PostMapping("/{id}/delete") @Transactional public void delete(Principal p,@PathVariable long id){long user=owner(p);lock(user);var tree=required(user,id);if(tree.sourceKey()!=null&&db.queryForObject("SELECT COUNT(*) FROM dismissed_relationship_trees WHERE user_id=? AND source_key=?",Integer.class,user,tree.sourceKey())==0)db.update("INSERT INTO dismissed_relationship_trees(user_id,source_key) VALUES(?,?)",user,tree.sourceKey());db.update("DELETE FROM reviewed_relationship_trees WHERE user_id=? AND id=?",user,id);}
 private Card card(Tree tree){return new Card(tree.id(),tree.sourceKey(),tree.name(),tree.reason(),tree.confidence(),tree.nodes().size(),tree.nodes().stream().limit(6).toList(),tree.version());}
 private Tree proposal(long user,String key){return generate(user).trees().stream().filter(tree->tree.sourceKey().equals(key)).findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Suggestion no longer available"));}
 private Generated generate(long user){
  var entries=book.allEntries(user);Map<Long,Entry> contacts=new LinkedHashMap<>();entries.forEach(c->contacts.put(c.id(),c));Map<String,Group> groups=new LinkedHashMap<>();
  for(Entry contact:entries){
   for(String label:contact.groups())if(!Set.of("my contacts","mycontacts","all contacts","allcontacts","imported","other contacts","othercontacts","starred in android").contains(normal(label)))add(groups,"LABEL",label,"Saved contact label: "+label,"Strong clue",90,contact,"Connection");
   if(!contact.organization().isBlank())add(groups,"ORGANIZATION",contact.organization(),"Shared organization: "+contact.organization(),"Strong clue",90,contact,"Colleague");
   String kinship=kinship(contact.displayName());if(kinship!=null)add(groups,"FAMILY","Family clues","Explicit relationship words in saved contact names; confirm each role","Needs review",95,contact,kinship);
   for(String email:contact.emails()){int at=email.lastIndexOf('@');if(at>0&&at<email.length()-1){String domain=email.substring(at+1).toLowerCase(Locale.ROOT);if(domain.matches("[a-z0-9.-]+\\.[a-z]{2,}")&&!MAIL_PROVIDERS.contains(domain))add(groups,"DOMAIN",domain,"Shared email domain; this does not prove a workplace relationship","Needs review",65,contact,"Connection");}}
   String name=contact.displayName().trim();Matcher suffix=java.util.regex.Pattern.compile("(?:\\(([^()]{2,60})\\)|\\s[-|]\\s([^|]{2,60}))$").matcher(name);if(suffix.find()){String tag=suffix.group(1)==null?suffix.group(2):suffix.group(1);if(!GENERIC.contains(normal(tag)))add(groups,"NAME_TAG",tag,"Matching tag in saved names: "+tag,"Needs review",60,contact,"Connection");}
   String[] words=name.split("\\s+");if(words.length>1){String token=words[0];if(token.matches("[A-Z][A-Z0-9]{1,11}")&&!Set.of("DR","MR","MRS","MS","SRI","SHRI","CEO","MD").contains(token))add(groups,"NAME_TAG",token,"Shared abbreviation in saved names: "+token,"Needs review",60,contact,"Connection");String last=words[words.length-1].replaceAll("[^\\p{L}]","");if(last.length()>=4&&!GENERIC.contains(normal(last)))add(groups,"SHARED_NAME",last,"Shared final name only; family ties and individual roles are unknown","Weak clue",30,contact,"Connection");}
  }
  db.query("SELECT c.name,a.contact_id FROM circles c JOIN address_book_circle_contacts a ON a.circle_id=c.id JOIN address_book_contacts b ON b.id=a.contact_id WHERE c.owner_user_id=? AND b.user_id=? ORDER BY c.id,a.contact_id",rs->{Entry contact=contacts.get(rs.getLong(2));if(contact!=null)add(groups,"CIRCLE",rs.getString(1),"Existing private contact circle: "+rs.getString(1),"Strong clue",80,contact,"Connection");},user,user);
  int small=(int)groups.values().stream().filter(g->g.nodes().size()<3).count();Set<String> signatures=new HashSet<>();List<Tree> trees=new ArrayList<>();
  for(Group group:groups.values().stream().filter(g->g.nodes().size()>=3).sorted(Comparator.comparingInt(Group::rank).reversed().thenComparing(g->g.name().toLowerCase(Locale.ROOT))).toList()){String signature=normal(group.name())+"|"+group.nodes().keySet().stream().sorted().toList().toString();if(!signatures.add(signature))continue;trees.add(new Tree(null,group.key(),group.name(),group.reason(),group.confidence(),List.copyOf(group.nodes().values()),0));}
  return new Generated(entries.size(),small,trees);
 }
 private void add(Map<String,Group> groups,String kind,String label,String reason,String confidence,int rank,Entry contact,String relation){String key=hash(kind+"|"+normal(label));Group group=groups.computeIfAbsent(key,k->new Group(k,label.trim().substring(0,Math.min(200,label.trim().length())),reason,confidence,rank,new LinkedHashMap<>()));group.nodes().putIfAbsent(contact.id(),new Node("c"+contact.id(),contact.id(),contact.displayName(),relation,null,null));}
 private static String kinship(String name){String text=" "+normal(name)+" ";for(var role:List.of(new String[]{"Father","father","dad","daddy","papa","nanna"},new String[]{"Mother","mother","mom","mummy","amma"},new String[]{"Brother","brother","bro"},new String[]{"Sister","sister","sis","akka","chelli"},new String[]{"Son","son"},new String[]{"Daughter","daughter"},new String[]{"Spouse","wife","husband","spouse"},new String[]{"Grandfather","grandfather","grandpa"},new String[]{"Grandmother","grandmother","grandma"})){for(int i=1;i<role.length;i++)if(text.contains(" "+role[i]+" "))return role[0];}return null;}
 private void validate(long user,Save input){if(input.nodes()==null||input.nodes().size()<3||input.nodes().size()>50000)throw bad("Save a tree with at least three people");Map<String,Node> nodes=new HashMap<>();Set<Long> ids=new HashSet<>();for(Node node:input.nodes()){if(nodes.put(node.key(),node)!=null)throw bad("Tree node keys must be unique");if(node.contactId()!=null&&!ids.add(node.contactId()))throw bad("A person can appear once in each tree");}if(!ids.isEmpty()&&book.entries(user,new ArrayList<>(ids)).size()!=ids.size())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"A selected contact is no longer in your private address book");for(Node node:input.nodes()){Set<String> path=new HashSet<>();Node current=node;while(current!=null){if(!path.add(current.key()))throw bad("A tree cannot contain a circular branch");if(path.size()>100)throw bad("Keep each branch within 100 levels");if(current.parentKey()!=null&&!nodes.containsKey(current.parentKey()))throw bad("Choose an existing connection point");current=current.parentKey()==null?null:nodes.get(current.parentKey());}}}
 private Tree required(long user,long id){var rows=db.query("SELECT * FROM reviewed_relationship_trees WHERE user_id=? AND id=?",(rs,n)->decode(rs.getLong("id"),rs.getString("source_key"),rs.getString("tree_data"),rs.getLong("version")),user,id);if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Tree not found");return rows.getFirst();}
 private String encode(Save input){try{return encryption.encrypt(json.writeValueAsString(new Tree(null,null,input.name().trim(),Objects.requireNonNullElse(input.reason(),"Reviewed private tree"),"Reviewed",input.nodes(),0)));}catch(Exception e){throw new IllegalStateException("Tree could not be saved",e);}}
 private Tree decode(long id,String key,String data,long version){try{Tree value=json.readValue(encryption.decrypt(data),Tree.class);return new Tree(id,key,value.name(),value.reason(),"Reviewed",value.nodes(),version);}catch(Exception e){throw new IllegalStateException("Tree could not be read",e);}}
 private void lock(long user){db.queryForObject("SELECT id FROM users WHERE id=? FOR UPDATE",Long.class,user);}
 private static String normal(String value){return Normalizer.normalize(value,Normalizer.Form.NFKC).toLowerCase(Locale.ROOT).replaceAll("[^\\p{L}\\p{N}]+"," ").trim().replaceAll("\\s+"," ");}
 private static String hash(String value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
 private static ResponseStatusException bad(String message){return new ResponseStatusException(HttpStatus.BAD_REQUEST,message);}
}
